<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\TenantRootVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\Holder\TenantRootAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantRootAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantRootAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that isRoot returns null on a freshly created holder.
         */
        public function testRootNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTenantRootAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isRootAssigned());
            $this->assertNull($holder->isRoot());
        }
}
class ImplWithTenantRootAttributeHolderUnitTest
{
  use TenantRootAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRootRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRoot();
    }}
